-- GENERATED by `wfj generate` from data/gossip/gossip-2d.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["2d04225d8b85b207"] = { "Presta attenzione, soldato! Devi portare questo segnalatore al Cimitero di Nevealta e piantarlo! Proteggilo abbastanza a lungo perché il mio grifone possa agganciarlo.\n\nSe il mio grifone ottiene un punto d'attacco preciso, Mulv e la sua banda saranno umiliati!", "." },
  ["2d045a9bd345d6b6"] = { "Scommetto che al mio amico Gruk piacerebbe questa pietra per la lancia che sta costruendo! È molto affilata... spero che gli piaccia.", "." },
  ["2d0afd4db9f7bcc9"] = { "Molto bene. Guerrieri delle distese ghiacciate, sorgete! Vi ordino di combattere, uccidere e morire per il vostro padrone! Che nessuno sopravviva!", "." },
  ["2d0f8cade67d1a63"] = { "<Valennia fa una smorfia di dolore mentre si sposta per guardarti.>\r\n\nNon guardarmi così. Starò bene. Nonostante gli sforzi dei guaritori apprensivi dell'alto anziano, sarò di nuovo in piedi e in grado di combattere in un attimo.\r\n\nOra vai... non lasciare che questo vecchio soldato ti trattenga. I venti ti porteranno fortuna nel tuo viaggio, lo so.", "." },
  ["2d112394cad929fb"] = { "Prima del suo esilio, Alamorte tentava di creare una progenie impura. Mezzosangue che non solo sarebbero stati immuni ai poteri e alle capacità innati dei loro Aspetti, ma anche sotto il completo controllo di Alamorte.\n\nSembra che dove il padre ha fallito, Nefarian possa esserci riuscito, almeno in parte.\n\nFu Ysera, Aspetto dei Sogni, a vedere gli abomini e a costringerci ad agire. Se questi draghi 'cromatici' esistono, vanno distrutti.", "." },
  ["2d11351a8fd85ced"] = { "Abbiamo metà del silithyst che ci serve. Ce la possiamo fare!", "." },
  ["2d198d6b923749ff"] = { "Questi ordini devono arrivare all'alto generale Abbendis!", "." },
  ["2d1a39af5cfe7ca2"] = { "Si dice che Kel'Thuzad cerchi la leggendaria Atiesh, Granbastone del Guardiano.\n\nSì, proprio il bastone che un tempo impugnava Medivh.", "." },
  ["2d21d3b171390cc7"] = { "Ho sentito che ci sono dei pesci enormi che sanno camminare sulla terra per cacciare, e mangiano le persone!", "." },
  ["2d228add02bd838c"] = { "Ascolterai queste parole, duca infame! Non sono il cagnolino del ⟦Twilight's Hammer=Martello del Crepuscolo⟧! Sono qui per sfidarti! Vieni! Vieni a incontrare la tua morte...", "." },
  ["2d2f6cb8b932efa2"] = { "%s chiede aiuto!", "." },
  ["2d379281255d120f"] = { "Ho poco tempo per sedermi a chiacchierare con te. Se desideri uno dei miei destrieri, cerca Velma laggiù: ti insegnerà a cavalcare un destriero scheletrico.\r\n\nNon vorrei che facessi del male a uno dei miei splendidi cavalli con la tua ignoranza.", "." },
  ["2d3ccfb27940744c"] = { "Finalmente il siero è pronto, {name}. Ora avvicinati. Dobbiamo parlare.", "." },
  ["2d4b0e0f80304739"] = { "Tornerò in fretta da Vahlarriel. Finisci quelli che puoi... da qui in poi dovrei cavarmela senza aiuto.", "." },
  ["2d52b93d5c309f1d"] = { "Di questo passo avrei potuto raccoglierli da me!", "." },
  ["2d52ee0b95f9830f"] = { "Puoi dirmi come posso ottenere un ⟦Videre Elixir=Elisir Videre⟧?", "." },
  ["2d55fd7bc138b444"] = { "$962w Stormpike Commander e $950w Stormpike Lieutenant.", "." },
  ["2d5abf1268f042db"] = { "Ti porgo un caloroso saluto, {class}, come fa la Shattered Hand.\n\nNon fare quella faccia sorpresa, {name}. Ci sono ombre perfino sui posatoi più alti di Orgrimmar... qualcosa deve pur nascondersi lì. La Shattered Hand assume quel ruolo volentieri. Thrall, pur nel suo cuore buono, riconosce che la Shattered Hand è necessaria per garantire la sicurezza di orchi e troll.\n\nMa tu non sei qui per parlare dei miei affari, sei qui per qualcos'altro.", "." },
  ["2d62f60f84df0acc"] = { "Abbiamo ordini dall'alto di distruggere Rajaxx. Eliminare con estremo pregiudizio, se vogliamo essere tecnici.", "." },
  ["2d641af1c81b4846"] = { "L'unico limite è l'immaginazione, <amico/amica> <mio/mia>: se riesci a capire come forgiarlo, puoi farlo, imballarlo e spedirlo ai rivenditori di tutto il mondo. Certo, poi c'è da occuparsi del marketing. Facciamo così: per ora limitiamoci alla parte della forgiatura, ok?", "." },
  ["2d666fd568592f96"] = { "Non sono in grado di elaborare il tuo riferimento cronologico rispetto alla registrazione di questi dati, mi scuso.\n\nSebbene il nano conservi gran parte della sintonia mentale dei Terrigeni con la composizione di pietra di Azeroth, il ritorno a una biomassa vivente resta la principale degenerazione della matrice. I nani si nutrono e procreano con mezzi tipici delle altre biomasse standard.\n\nI Creatori considerano il nano una variante accettabile, degna di genesi a pieno titolo.", "." },
  ["2d847a0b977f0f8e"] = { "<Thrall ride.>\n\nPreso nota... Ora presta attenzione, {name}. La madre della covata dello Stormo dei Draghi Neri, Onyxia, è stata stanata dalla sua posizione di potere a ⟦Stormwind=Roccavento⟧. È fuggita, rifugiandosi nella sua tana ad ⟦Dustwallow Marsh=Acquemorte⟧.\n\nNon possiamo permetterle di vivere così vicino alle nostre capitali. Dobbiamo colpire prima di essere colpiti!\n\nVoglio che venga distrutta, {name}.", "." },
  ["2d851d089a899976"] = { "Oh no! È fuori controllo! Scappate!", "." },
  ["2d902ba67e18200f"] = { "Hai l'aria un po' spaesata. Posso aiutarti a trovare qualcosa?", "." },
  ["2da3c853384e60fe"] = { "La battaglia è vinta. Per ora, la minaccia del Flagello è stata respinta. Le nostre risorse possono essere impiegate per aiutarti, in segno di gratitudine e in vista del futuro.", "." },
  ["2da94b0142a45c98"] = { "Hai bisogno di aiuto?", "." },
  ["2db214a6388152cf"] = { "Ti stavo aspettando, {name}. Sei <pronto/pronta> ad aiutarci nel ⟦Arathi Basin=Bacino d'Arathi⟧?", "." },
  ["2db53061d7c66646"] = { "Salute, {name}. Siamo giunti da ⟦Moonglade=Radaluna⟧ per diffondere ovunque lo spirito della Celebrazione della Luna.\n\nNon vuoi unirti ai nostri festeggiamenti?", "." },
  ["2dbb413a80526767"] = { "Grazie, stalliere. Ti prego, prendi l'animale.", "." },
  ["2dbc60bce450e4d0"] = { "Se ho dimenticato? Certo che sì... Ho dimenticato l'amore, la felicità... la vita stessa.", "." },
  ["2dc85f6b3dc32094"] = { "Non ci sarà scampo!", "." },
  ["2dd0ba474a2b35fd"] = { "Ti prego, dimmi di più.", "." },
  ["2dda6733be1468d6"] = { "Dov'è il quartiermastro dei Lupi Bianchi?", "." },
  ["2dda73b2079667ea"] = { "Salve, <buon/buona> <signore/signora>. Siediti, e mangia qualcosa se hai fame. Non badare al mio ricamo: ti sto ascoltando...", "." },
  ["2ddb2c504bcae86d"] = { "Mi stai davvero chiedendo dov'è il fabbro? Non hai mai sentito parlare della ⟦Great Forge=Grande Forgia⟧!? Tutti i nostri migliori fabbri si riuniscono lì per forgiare armi e armature!\n\nSta proprio nel bel mezzo di ⟦Ironforge=Forgiardente⟧, ed è lì che troverai uno dei nostri fabbri più brillanti, ⟦Bengus Deepforge=Bengus Forgiafonda⟧.", "." },
  ["2ddd674aab64d2cb"] = { "%s prepara la sua siringa.", "." },
  ["2dddd33a79fbaeab"] = { "Che vuoi? *hic*", "." },
  ["2ddef0b309cef801"] = { "Finalmente un po' di pietà! Ci hanno dato qualcosa da bere!", "." },
  ["2de45d1f1c649a7b"] = { "Ecco fatto. La nostra lezione sull'evocazione è terminata. Tra poco comincerà una nuova lezione, quindi se vuoi ripassare, resta pure.", "." },
  ["2de4990e94a0c823"] = { "Io cerco qualcuno, {class}. Ti prego, lasciami stare... è importante che trovi questa persona.", "." },
  ["2dec9de91048f5bc"] = { "Come faccio a combinare qualcosa con il Flagello che imperversa qui dentro?!", "." },
  ["2df2b98a302364e0"] = { "Una volta ho visto un gigante del mare. Non è qualcosa che vorrei rivedere. Burp!", "." },
  ["2df97ef165aa60f5"] = { "Chi osa entrare nel mio dominio! Venite! Venite, e siate divorati!", "." },
})
